      description: "List of key injuries/absences formatted as 'Player Name (Status) - Reason'.",
      items: { type: Type.STRING }
    },
    odds: {
      type: Type.OBJECT,
      properties: {
        winner: {
          type: Type.STRING,
          description: "The predicted odds for the winning team as a string (e.g., '+150' for American, '2.50' for Decimal)."
        },
        loser: {
          type: Type.STRING,
          description: "The predicted odds for the losing team as a string (e.g., '-180' for American, '1.65' for Decimal)."
        }
      },
      required: ["winner", "loser"]
    },
    oddsDetails: {
      type: Type.OBJECT,
      description: "Detailed analysis of line movement and bookmaker discrepancies.",
      properties: {
        winnerOpen: { type: Type.STRING, description: "The opening moneyline/spread odds." },
        winnerCurrent: { type: Type.STRING, description: "The current consensus moneyline/spread odds." },
        movement: { type: Type.STRING, enum: ["Steam", "Fading", "Stable"], description: "Direction of betting action." },
        sharpConsensus: { type: Type.STRING, description: "Where the sharp money (Pinnacle/Circa) is going." },
        publicConsensus: { type: Type.STRING, description: "Where the public tickets are (e.g. '80% on Home')." },
        bookmakers: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
