              odds: { type: Type.STRING },
              value: { type: Type.STRING, enum: ["Best", "Average", "Poor"] }
            }
          }
        }
      },
      required: ["winnerOpen", "winnerCurrent", "movement", "bookmakers"]
    },
    matchupHistory: {
        type: Type.ARRAY,
        description: "List of last 3 head-to-head matches between these two teams.",
        items: {
             type: Type.OBJECT,
             properties: {
                 date: { type: Type.STRING, description: "Date of the match" },
