import { AnalyticsIcon, PlusIcon, CheckIcon, SearchIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string }> = {
    High: { bg: 'bg-green-900/50', text: 'text-green-300', border: 'border-green-800' },
    Medium: { bg: 'bg-amber-900/40', text: 'text-amber-300', border: 'border-amber-700' },
    Low: { bg: 'bg-rose-900/50', text: 'text-rose-300', border: 'border-rose-800' },
};

const convertAmericanToDecimal = (americanOdds: string): string => {
    const odds = parseInt(americanOdds, 10);
    if (isNaN(odds)) return americanOdds;

    let decimalOdds: number;
    if (odds > 0) {
        decimalOdds = (odds / 100) + 1;
    } else {
        decimalOdds = (100 / Math.abs(odds)) + 1;
    }
    return decimalOdds.toFixed(2);
};

// Helper to parse injury string
const parseInjury = (injuryString: string) => {
    // Expected format: "Player Name (Status) - Reason"
    // Regex handles optional reason part
    const match = injuryString.match(/^(.*?)\s*\((.*?)\)(?:\s*-\s*(.*))?$/);
    if (match) {
        return {
            player: match[1].trim(),
            status: match[2].trim(),
            reason: match[3] ? match[3].trim() : ''
        };
    }
    // Fallback if format doesn't match
    return { player: injuryString, status: 'Report', reason: '' };
};

const getStatusColor = (status: string) => {
    const s = status.toLowerCase();
    if (s.includes('out') || s.includes('ir') || s.includes('suspend') || s.includes('injure')) {
        return 'text-red-400 bg-red-900/20 border-red-500/30';
    }
    if (s.includes('doubt') || s.includes('question') || s.includes('day-to-day') || s.includes('gtd')) {
        return 'text-amber-400 bg-amber-900/20 border-amber-500/30';
    }
    if (s.includes('prob') || s.includes('available')) {
        return 'text-green-400 bg-green-900/20 border-green-500/30';
    }
    return 'text-slate-400 bg-zinc-800 border-zinc-700';
};

