                            >
                                {source.web.title || new URL(source.web.uri).hostname}
                            </a>
                        )
                    ))}
                 </div>
            </div>
        )}
    </div>
  );
});

import type React from 'react';

// FIX: Define ConfidenceLevel type for predictions.
export type ConfidenceLevel = 'High' | 'Medium' | 'Low';

export interface PropBet {
  player: string;
  bet: string; // e.g. "Over 24.5 Points"
  line: string; // e.g. "24.5"
  stat: string; // e.g. "Points"
  type: 'MORE' | 'LESS'; // Derived from "Over" or "Under"
  odds: string;
  probability: string;
  ev?: number; // Expected Value percentage
  analysis?: string; // Short reasoning
  isBestValue?: boolean; // New field for "AI Choice"
}

export interface GameOdds {
  spread?: string;
  moneyline?: string;
  total?: string;
}

export interface BookmakerOdds {
  book: string; // e.g., "DraftKings", "FanDuel"
  odds: string; // e.g., "-110"
  value: 'Best' | 'Average' | 'Poor';
}

export interface OddsAnalysis {
  winnerOpen: string; // Opening line
  winnerCurrent: string; // Current line
  movement: 'Steam' | 'Fading' | 'Stable'; // Interpretation of movement
  sharpConsensus?: string; // e.g. "Pinnacle leans Home"
  publicConsensus?: string; // e.g. "78% tickets on Home"
  bookmakers: BookmakerOdds[];
}

export interface MatchupGame {
  date: string;
  homeTeam: string;
  homeScore: string;
  awayTeam: string;
  awayScore: string;
  winner: string;
}

// FIX: Define the main Prediction data structure.
export interface Prediction {
  winner: string;
  loser: string;
  confidence: ConfidenceLevel;
  confidenceScore: number;
  ev?: number; // Overall Expected Value of the main pick
  kellyRecommendation?: string; // e.g. "1.5 Units"
  analysis: string;
  injuries?: string[]; // Added to match schema
  odds: {
    winner: string;
    loser: string;
  };
  oddsDetails?: OddsAnalysis; // New detailed odds data
  matchupHistory?: MatchupGame[]; // Head-to-head history
  props?: PropBet[];
  sources?: Array<{
    web?: {
      // FIX: Made uri and title optional to match GroundingChunk type from Gemini API.
      uri?: string;
      title?: string;
    };
  }>;
}

