export const getSchedule = async (sport: string): Promise<Game[]> => {
  const sportQuery = sport === 'NFL' ? 'NFL Football' : sport;

  // OPTIMIZED PROMPT: Short, direct instructions to reduce latency and token usage.
  // Explicitly requests "Live" details (Quarter, Period) to satisfy the "3rd quarter" requirement.
  const prompt = `
    Fetch ${sportQuery} schedule & live scores for TODAY (${new Date().toLocaleDateString()}).
    CRITICAL: For LIVE games, extract the exact Period/Quarter (e.g. "Q1", "Q3", "Halftime").
    Include upcoming games for the next 24 hours.

    Return STRICT JSON ONLY. No markdown.
    Format:
    {
      "games": [
        {
          "id": "Home-Away-Date",
          "homeTeam": "Name",
          "awayTeam": "Name",
          "time": "Live Q3 5:12" or "7:00 PM EST",
          "date": "Today" or "Oct 25",
          "status": "Live" | "Scheduled" | "Finished",
          "score": "24-17",
          "odds": { "spread": "-5.5", "total": "48.5", "moneyline": "-150" }
        }
      ]
    }

    Sort order: Live games first, then by start time.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.0, // Reduced temperature for faster, deterministic output
      }
    });

    const text = response.text || '';
    const jsonString = text.replace(/^```json\s*/, '').replace(/```$/, '').trim();

    try {
        const data = JSON.parse(jsonString);
        return data.games || [];
    } catch (parseError) {
        // Fallback: simple text extraction or return empty if JSON fails (fail fast)
        console.warn("JSON parse failed, returning empty to avoid crash", parseError);
        return [];
    }
  } catch (error) {
    console.error("Failed to fetch schedule:", error);
    return [];
  }
};

